#!/usr/bin/env python3
"""Build the dependency-free Mediaserver website and minipliy.net directory."""
from pathlib import Path
from html import escape
import shutil
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'web/mediaserver'; PORTAL=ROOT/'web/portal'
APP_STORE='https://apps.apple.com/de/app/mediaserver-eigene-medien/id6828504596'
GITHUB='https://github.com/Minipliy/Mediaserver'
GUIDE=GITHUB+'/blob/main/docs/ANLEITUNG.md'
HYSE_STORE='https://apps.apple.com/de/app/hyse/id6811359623'
CONTACT='''Lukas Hammer<br>Falkenstraße 12<br>01067 Dresden<br>Deutschland<br>E-Mail: <a href="mailto:hyse@minipliy.net">hyse@minipliy.net</a>'''

def page(path,title,description,body,portal=False,noindex=False):
    root=PORTAL if portal else SITE
    host='https://minipliy.net' if portal else 'https://mediaserver.minipliy.net'
    brand='minipliy' if portal else 'Mediaserver'
    icon='/assets/mediaserver.png' if portal else '/assets/app-icon.png'
    links=[('/', 'Start'),('/einrichtung','Einrichtung'),('/support','Support'),(GITHUB,'GitHub')]
    if portal: links=[('https://hyse.minipliy.net','Hyse'),('https://mediaserver.minipliy.net','Mediaserver')]
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==path else '')+f'>{label}</a>' for url,label in links)
    logo=f'<a class="brand" href="/">'+('' if portal else f'<img src="{icon}" width="40" height="40" alt="">')+f'<span>{brand}</span></a>'
    footer=''.join(f'<a href="{u}">{label}</a>' for u,label in [('/support','Support'),(GITHUB,'GitHub'),(GUIDE,'Anleitung'),('/datenschutz','Datenschutz'),('/agb','Nutzungsbedingungen'),('/impressum','Impressum')])
    if portal: footer='<a href="/datenschutz">Datenschutz</a><a href="/impressum">Impressum</a>'
    html=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · {brand}</title><meta name="description" content="{escape(description,quote=True)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{host+path}"><meta name="theme-color" content="#080f19"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{host+path}"><meta property="og:image" content="{host+icon}"><link rel="icon" href="{icon}"><link rel="stylesheet" href="/assets/site.css?v=20261107"></head><body><a class="skip" href="#inhalt">Zum Inhalt springen</a><header class="header"><nav class="nav wrap" aria-label="Hauptnavigation">{logo}<div class="navlinks">{nav}</div><details class="mobile"><summary>Menü</summary><div class="navlinks">{nav}</div></details></nav></header><main id="inhalt" class="wrap">{body}</main><footer class="footer"><div class="wrap"><div class="footer-top">{logo}<nav class="footerlinks" aria-label="Weitere Informationen">{footer}</nav></div><p>© 2026 Lukas Hammer · {'Zwei Apps. Ein Zuhause.' if portal else 'Deine Medien. Auf deinem Server.'} &nbsp; <a href="https://minipliy.net/">minipliy</a> · <a href="https://hyse.minipliy.net/">Hyse</a></p></div></footer></body></html>'''
    html=html.replace(' ↗</a>',' <span aria-hidden="true">↗</span></a>').replace(' →</a>',' <span aria-hidden="true">→</span></a>')
    dest=root/('index.html' if path=='/' else path.strip('/')+'/index.html')
    if path=='/404': dest=root/'404.html'
    dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(html)

def intro(kicker,title,text):
    return f'<div class="page-intro"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{text}</p></div>'
def legal(title,body,stand='29. Oktober 2026'):
    return '<article class="legal">'+intro('Rechtliche Informationen',title,f'Stand: {stand}')+body+'</article>'

wave=''.join(f'<i style="--h:{h}%"></i>' for h in [20,38,70,45,90,60,100,50,35,80,65,40,85,55,95,45,70,30])
home=f'''<section class="hero"><div><p class="eyebrow">Dein Medienplayer für iPhone & iPad</p><h1>Deine Medien.<br>Dein Server.<br><span>Überall dabei.</span></h1><p class="lead">Musik, Filme und Serien aus deiner eigenen Sammlung. Streame von deinem Server oder nimm deine Favoriten offline mit.</p><div class="actions"><a class="button" href="{APP_STORE}">Im App Store laden ↗</a><a href="/einrichtung">So richtest du sie ein</a></div><div class="status"><span class="dot" aria-hidden="true"></span>Kostenlos für iPhone und iPad mit iOS 17 oder neuer</div></div><figure class="library-figure"><div class="library" role="img" aria-label="Schematische Darstellung der App: Musik mit Titeln, Alben und Interpreten, Filme und Serien sowie fertige Downloads für unterwegs"><div class="library-top"><span>DEINE SAMMLUNG</span><span>♫ &nbsp; ▷ &nbsp; ↓</span></div><p class="library-title">Alles, was du magst.</p><div class="media-row"><div class="media-symbol" aria-hidden="true">♫</div><div><b>Musik, die bleibt.</b><small>Titel · Alben · Interpreten</small></div></div><div class="media-row"><div class="media-symbol video" aria-hidden="true">▷</div><div><b>Dein nächster Filmabend.</b><small>Filme · Serien · Staffeln</small></div></div><div class="media-row"><div class="media-symbol download" aria-hidden="true">↓</div><div><b>Auch ohne Empfang.</b><small>Deine fertigen Downloads</small></div></div><div class="player" aria-hidden="true"><div class="play">▶</div><div class="wave">{wave}</div><span class="player-time">DEIN MIX</span></div></div><figcaption class="library-caption">Die Medienbereiche auf einen Blick · schematische Darstellung</figcaption></figure></section>
<div class="facts"><span><strong>Eigener Server</strong> statt fremder Mediathek</span><span><strong>Kein Abo</strong> in der App</span><span><strong>Keine Werbung</strong> und kein Tracking</span><span><strong>Offline</strong> nach dem Download</span></div>
<section class="section" id="entdecken"><div class="split"><div><p class="eyebrow">Deine Sammlung, gut sortiert</p><h2>Von der ersten Note<br>bis zum Abspann.</h2><p class="lead">Ein Ort für deine eigenen Dateien. Mit den Funktionen, die du beim Hören und Schauen wirklich brauchst.</p></div><div><div class="feature"><span class="feature-num">01 /</span><div><h3>Musik mitnehmen</h3><p>Stöbere durch Titel, Alben und Interpreten. Erstelle Playlists und höre weiter, wenn das Display aus ist — mit Steuerung auf dem Sperrbildschirm.</p></div></div><div class="feature"><span class="feature-num">02 /</span><div><h3>Filme und Serien genießen</h3><p>Öffne Videos, spule zur richtigen Stelle und setze die Wiedergabe später fort. Serien und Staffeln erkennt der Server an deiner Ordnerstruktur.</p></div></div><div class="feature"><span class="feature-num">03 /</span><div><h3>Für unterwegs herunterladen</h3><p>Speichere Titel, Filme und einzelne Folgen auf deinem Gerät. Fertige Downloads bleiben ohne Internet abspielbar. Neue Downloads nutzen standardmäßig WLAN.</p></div></div></div></div></section>
<section class="section"><p class="eyebrow">Dein Server. Deine Entscheidung.</p><p class="statement">Deine Originale bleiben auf <em>deinem Speicher.</em> Du bestimmst, womit sich die App verbindet.</p><div class="split"><p>Mediaserver enthält keinen Film- oder Musikkatalog und benötigt kein Nutzerkonto beim App-Entwickler. Du verbindest die App über eine HTTPS-Adresse und ein Zugangs-Token mit einem kompatiblen Server.</p><p>Die Zugangsdaten liegen im iOS-Schlüsselbund. Bibliothek, Playlists und Wiedergabepositionen werden lokal zwischengespeichert; Downloads belegen Speicher auf deinem Gerät. <a href="/datenschutz">Mehr zum Datenschutz</a></p></div></section>
<section class="section"><div class="section-title"><p class="eyebrow">In drei Schritten</p><h2>Von deiner Festplatte<br>in deine Hand.</h2></div><div class="steps"><div class="step"><span>01 — VORBEREITEN</span><h3>Server einrichten.</h3><p>Betreibe das kompatible Mediaserver-Backend, etwa auf einem Raspberry Pi mit SSD. Für den Fernzugriff brauchst du einen erreichbaren HTTPS-Zugang.</p></div><div class="step"><span>02 — VERBINDEN</span><h3>Deine Adresse eingeben.</h3><p>Trage Serveradresse und API-Token in der App ein. Die Bibliothek wird geladen und nach Musik, Videos und Playlists gegliedert.</p></div><div class="step"><span>03 — GENIESSEN</span><h3>Abspielen. Oder mitnehmen.</h3><p>Streame zu Hause und unterwegs. Lade deine Auswahl vorher herunter, wenn du später ohne Internet hören oder schauen möchtest.</p></div></div><a class="feature-link" href="/einrichtung">Zur Einrichtung und den Voraussetzungen →</a></section>
<section class="section" id="open-source"><div class="section-title"><p class="eyebrow">Offen und selbst gemacht</p><h2>Der ganze Code.<br>Für alle einsehbar.</h2></div><p class="lead">Server, App und Web-Player sind offen auf GitHub, unter der MIT-Lizenz. Gedacht für alle, die ihre Privatsphäre behalten wollen: Deine Medien bleiben bei dir zu Hause, ohne Abo, Werbung oder Tracking. Eine Anleitung erklärt die Einrichtung auf einem Raspberry Pi Schritt für Schritt, auch ohne Vorkenntnisse.</p><p>Ehrlicher Hinweis: Code, App und Texte wurden mit künstlicher Intelligenz (Claude von Anthropic) erstellt.</p><div class="actions"><a class="button" href="'''+GUIDE+'''">Anleitung zum Einrichten ↗</a><a href="'''+GITHUB+'''">Code auf GitHub ↗</a></div></section>
<div class="closing"><div><p class="eyebrow">Gut zu wissen</p><h2>Fragen vor dem ersten Play?</h2><p>Antworten zu Server, Formaten und Offline-Wiedergabe.</p></div><div class="closing-actions"><a class="button" href="{APP_STORE}">Im App Store laden ↗</a><a class="button secondary" href="/support">Zum Support ↗</a></div></div>'''
page('/','Deine Medien. Dein Server. Überall dabei.','Mediaserver für iPhone und iPad: eigene Musik, Filme und Serien streamen und offline mitnehmen. Ein kompatibler eigener Server ist erforderlich.',home)
faqs=[('Was brauche ich für die App?','Ein iPhone oder iPad mit iOS bzw. iPadOS 17 oder neuer sowie einen kompatiblen Mediaserver mit HTTPS-Adresse und API-Token. Die App allein stellt keinen Server und keine Medien bereit. <a href="/einrichtung">Voraussetzungen ansehen</a>.'),('Funktioniert die App mit jeder NAS oder jedem Medienserver?','Nein. Die App nutzt die Mediaserver-API dieses Projekts. Eine SMB-Freigabe, ein Plex-, Jellyfin- oder DLNA-Server allein genügt nicht. Dein Server muss die kompatiblen Bibliotheks-, Streaming- und Download-Endpunkte bereitstellen.'),('Die Verbindung funktioniert nicht. Was kann ich prüfen?','Kontrolliere HTTPS-Adresse, gültiges Zertifikat und API-Token. Prüfe anschließend, ob der Server läuft und von deinem aktuellen Netzwerk erreichbar ist. Im lokalen Netzwerk muss die iOS-Berechtigung für den Netzwerkzugriff erlaubt sein. Die App-Store-Version akzeptiert keine unverschlüsselten HTTP-Adressen.'),('Welche Dateien lassen sich abspielen?','Die Bibliothek erkennt gängige Musik- und Videodateien, unter anderem MP3, AAC, M4A, FLAC, WAV, MP4 und MOV. Auch Container wie MKV, AVI oder WebM können erkannt werden; die tatsächliche Wiedergabe hängt von den enthaltenen Codecs und deinem Gerät ab. Inkompatible Dateien müssen serverseitig vorab in ein geeignetes Format umgewandelt werden. Es gibt kein Echtzeit-Transcoding.'),('Wie funktionieren Downloads?','Öffne das Aktionsmenü einer Datei und wähle „Herunterladen“. Vollständig gespeicherte Dateien erscheinen im Tab „Downloads“. Du kannst sie dort ohne Internet abspielen oder lokal entfernen. Das Original auf deinem Server bleibt beim Entfernen eines Downloads erhalten.'),('Läuft ein Download im Hintergrund weiter?','Ja, iOS überträgt Downloads auch im Hintergrund. Bricht die Verbindung ab oder antwortet der Server kurz nicht, setzt die App den Download später an derselben Stelle fort. Startest du einen Download ohne Internet oder über Mobilfunk, merkt sich die App ihn und lädt ihn im WLAN. Beendest du die App manuell, kann iOS laufende Downloads abbrechen.'),('Warum fehlen Serien oder neue Dateien?','Ordne Serien zum Beispiel unter Serien/Serienname/Staffel 01/ ein. Wähle in der App unter „Server“ die Aktion „Bibliothek neu einlesen“. Prüfe bei fehlenden Dateien auch die Leserechte des Serverprozesses.'),('Wie entferne ich meine Daten?','Entferne Downloads einzeln im Download-Tab. „Server → Verbindung entfernen“ löscht die gespeicherte Verbindung aus dem Schlüsselbund; Downloads bleiben bestehen. Lösche die App vollständig, um ihren lokalen Dateibestand zu entfernen. Daten auf dem Server verwaltet dessen Betreiber. <a href="/datenschutz#loeschung">Details zur Löschung</a>.'),('Wo bekomme ich den Server?','Die Serversoftware ist kostenlos und offen <a href="'+GITHUB+'">auf GitHub</a>. Die <a href="'+GUIDE+'">Anleitung</a> zeigt Schritt für Schritt, wie du sie auf einem Raspberry Pi einrichtest; dafür brauchst du keine Vorkenntnisse.'),('Wo bekomme ich die App?','Mediaserver gibt es kostenlos <a href="'+APP_STORE+'">im App Store</a> für iPhone und iPad mit iOS bzw. iPadOS 17 oder neuer. Einen öffentlichen TestFlight-Test gibt es nicht.')]
faq=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)
page('/support','Support','Hilfe zur Mediaserver-App: Verbindung, kompatible Server, Dateiformate, Downloads und Kontakt.',intro('Mediaserver Support','Wie können wir helfen?','Hier findest du Antworten auf die häufigsten Fragen. Wenn du nicht weiterkommst, schreib uns eine E-Mail.')+f'''<div class="support-grid"><aside class="contact"><h2>Direkt Kontakt aufnehmen.</h2><p>Beschreibe kurz dein Problem und nenne App-Version, Gerätemodell, iOS-Version und die Schritte bis zum Fehler.</p><a class="button" href="mailto:hyse@minipliy.net?subject=Mediaserver%20Support">E-Mail schreiben ↗</a><p class="fine" style="margin-top:20px">hyse@minipliy.net</p><p class="fine">Bitte sende keine API-Tokens, Passwörter, privaten Medien oder ungeschwärzten Serverprotokolle. <a href="/datenschutz#kontakt">Datenschutz bei Supportanfragen</a></p></aside><div class="faq">{faq}</div></div>''')
setup='''<div class="note"><strong>Neu hier?</strong> Die <a href="'''+GUIDE+'''">Schritt-für-Schritt-Anleitung</a> erklärt die komplette Einrichtung mit einem Raspberry Pi, auch ohne Vorkenntnisse. Der Server ist kostenlos und offen <a href="'''+GITHUB+'''">auf GitHub</a>.</div><h2>1. Was du benötigst</h2><ul><li>Ein iPhone oder iPad mit iOS/iPadOS 17 oder neuer.</li><li>Einen Server mit kompatibler Mediaserver-API und Zugriff auf deine Medien. Die Serversoftware gibt es kostenlos <a href="'''+GITHUB+'''">auf GitHub</a>; ein Raspberry Pi mit SSD ist eine gute Grundlage (<a href="'''+GUIDE+'''">Anleitung</a>).</li><li>Eine HTTPS-Adresse mit gültigem Zertifikat und das vom Serverbetreiber vergebene API-Token.</li><li>Für Streaming eine Netzwerkverbindung; unterwegs zusätzlich ausreichenden Upload am Serverstandort.</li></ul><div class="note">Die App enthält keine Medien, stellt keinen Cloud-Speicher bereit und richtet keine Server-Hardware automatisch ein. Allgemeine NAS-, Plex-, Jellyfin- oder DLNA-Zugänge sind keine kompatible Mediaserver-API.</div><h2>2. Medien auf dem Server ablegen</h2><p>Kopiere deine eigenen Dateien mit einer eingerichteten Netzwerkfreigabe auf den Server, zum Beispiel im Finder über SMB. Die App selbst ist zum Durchsuchen, Abspielen und Herunterladen gedacht.</p><ul><li><code>Musik/Interpret/Album/Titel.m4a</code></li><li><code>Filme/Mein Film.mp4</code></li><li><code>Serien/Serienname/Staffel 01/S01E01.mp4</code></li></ul><p>Musiktitel, Alben und Interpreten werden soweit vorhanden aus den Audio-Tags gelesen. Nutze nur Inhalte, für deren Nutzung du die erforderlichen Rechte hast.</p><h2>3. App verbinden</h2><ol><li>Lade Mediaserver <a href="'''+APP_STORE+'''">im App Store</a> und öffne die App.</li><li>Trage die vollständige HTTPS-Serveradresse ein, die dir dein Serverbetreiber gegeben hat.</li><li>Gib das API-Token ein und tippe auf „Verbinden“.</li><li>Erlaube den lokalen Netzwerkzugriff, wenn dein Server im Heimnetz liegt.</li></ol><p>Die Verbindungsdaten werden im Schlüsselbund gespeichert. Unter „Server“ kannst du die Bibliothek neu einlesen lassen oder die Verbindung entfernen.</p><h2>4. Streaming und Offline-Wiedergabe</h2><p>Öffne einen Titel oder ein Video zum Abspielen. Über das Aktionsmenü kannst du Dateien herunterladen. Warte, bis die Datei im Tab „Downloads“ vollständig angezeigt wird, bevor du offline gehst.</p><p>Unter „Server → Downloads über Mobilfunk“ kannst du Mobilfunk für neue Downloads erlauben. Dein Mobilfunkanbieter kann dafür Datenvolumen berechnen.</p><h2>5. Kompatibilität und Aufbereitung</h2><p>Eine erkannte Dateiendung garantiert noch keine Wiedergabe. Entscheidend sind Container, Video- und Audiocodecs sowie dein Gerät. Für inkompatible Dateien kann der Server vorab eine MP4- oder M4A-Wiedergabekopie bereitstellen. Die Originale bleiben erhalten.</p><h2>Server-Software und technische Einrichtung</h2><p>Die zu dieser App gehörende Server-Software wird separat eingerichtet. Wenn du noch keinen kompatiblen Server betreibst, kontaktiere den Support zur Bereitstellung und Einrichtung der passenden Software. Kaufe nicht allein für die App neue Hardware, bevor die Kompatibilität geklärt ist.</p><p><a class="button" href="mailto:hyse@minipliy.net?subject=Mediaserver%20Server-Einrichtung">Server-Einrichtung anfragen ↗</a></p>'''
page('/einrichtung','Einrichtung & Voraussetzungen','Was du für Mediaserver brauchst und wie du deinen kompatiblen Server mit der iOS-App verbindest.','<article class="legal">'+intro('Vor dem ersten Start','Dein Server.<br>In deiner Hand.','Die App ist der Player. Deine eigene Serverinstallation liefert die Medien.')+setup+'</article>')
privacy=f'''<nav class="legal-nav" aria-label="Inhaltsübersicht"><a href="#verantwortlich">Verantwortlicher</a><a href="#website">Website</a><a href="#app">App</a><a href="#kontakt">Support</a><a href="#loeschung">Löschung</a><a href="#rechte">Deine Rechte</a></nav><section id="verantwortlich"><h2>1. Verantwortlicher und Geltungsbereich</h2><p>{CONTACT}</p><p>Diese Erklärung beschreibt die Website mediaserver.minipliy.net, die zugehörige Produktübersicht auf minipliy.net und die App „Mediaserver“. Sie unterscheidet zwischen unseren Websites und Supportangeboten, der lokalen Verarbeitung auf deinem Gerät und der Verarbeitung auf einem von dir gewählten Medienserver.</p></section><section id="website"><h2>2. Aufruf der Websites</h2><p>Zur Auslieferung verarbeitet der Webserver technisch notwendige Verbindungsdaten, insbesondere IP-Adresse, Zeitpunkt, angeforderte Adresse, Browserinformationen und übertragene Daten. Zweck ist die Bereitstellung, Sicherheit und Fehlerbehebung. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO; unser berechtigtes Interesse ist ein sicherer und funktionsfähiger Webauftritt.</p><p>Die Websites werden auf Serverinfrastruktur der STRATO GmbH, Otto-Ostrowski-Straße 7, 10249 Berlin, Deutschland, betrieben. STRATO stellt die Hosting-Infrastruktur bereit. Auf den neuen Produktseiten wird kein dauerhaftes HTTP-Zugriffsprotokoll geführt. Betriebs- und Fehlerprotokolle können technische Angaben enthalten; diese werden nur so lange aufbewahrt, wie sie für den sicheren Betrieb und die Fehlerbehebung erforderlich sind. Angaben, die im Einzelfall zur Aufklärung eines Sicherheitsvorfalls oder zur Erfüllung gesetzlicher Pflichten erforderlich sind, können zweckgebunden länger aufbewahrt werden.</p><h3>Keine Analyse, keine Werbe-Cookies</h3><p>Diese Seiten setzen keine Cookies und verwenden keinen lokalen Browserspeicher, keine Analyse- oder Werbeskripte und keine extern geladenen Schriftarten. Bilder und Gestaltung werden von unserer Website geladen. Es gibt keine eingebetteten Social-Media-Inhalte. Externe Seiten, beispielsweise Hyse oder Apple, werden erst beim Anklicken eines Links aufgerufen und unterliegen ihren eigenen Datenschutzhinweisen.</p></section><section id="app"><h2>3. Daten auf deinem iPhone oder iPad</h2><p>Die App verarbeitet deine eingegebene Serveradresse und dein API-Token, Medienmetadaten, Bibliotheks- und Playlistinformationen, Wiedergabepositionen, Download-Dateien und Einstellungen. Die Verbindung liegt im iOS-Schlüsselbund mit gerätegebundener Schutzklasse. Bibliothek und Playlists werden lokal zwischengespeichert, damit sie bei einer vorübergehend fehlenden Verbindung verfügbar bleiben.</p><p>Wiedergabepositionen und Einstellungen werden lokal gespeichert. Vor einem Download prüft die App den verfügbaren Speicherplatz, um zu große Downloads abzulehnen. Diese Speicherplatzinformation wird nicht an uns übermittelt. Downloads liegen im App-Verzeichnis und werden von der regulären Gerätesicherung ausgeschlossen; für andere lokale App-Daten können je nach Systemeinstellung Gerätebackups bestehen.</p><p>Die App enthält kein Analyse-, Werbe- oder Tracking-SDK und verlangt kein Nutzerkonto beim Entwickler. Sie greift nicht auf Kontakte, Standort, Mikrofon oder Apple Health zu. iOS kann für einen Server im Heimnetz nach Erlaubnis zum lokalen Netzwerkzugriff fragen. Die Berechtigung kann in den Systemeinstellungen geändert werden.</p><h3 id="ausfall">Ausfall-Warnungen</h3><p>Schaltest du in den Einstellungen „Bei Ausfall benachrichtigen“ ein, fragt das System nach der Erlaubnis für Mitteilungen. Die App übermittelt dann eine von Apple vergebene Geräteadresse für Mitteilungen (Push-Token) an deinen Medienserver und wiederholt das einmal pro Woche. Antwortet der Server nicht mehr, schickt ein Wächter des Serverbetreibers über den Apple Push Notification Service (Apple) eine Mitteilung an diese Adresse. Sie enthält nur den Hinweis auf den Ausfall und keine Inhalte aus deiner Bibliothek. Schaltest du die Funktion aus, meldet die App die Adresse nicht mehr; der Server löscht Adressen, die er 90 Tage lang nicht erhalten hat. Die Erlaubnis für Mitteilungen kannst du in den Systemeinstellungen widerrufen.</p><h2>4. Verbindung mit deinem Medienserver</h2><p>Die App übermittelt Anfragen über HTTPS an die von dir eingetragene Serveradresse. Der Server erhält notwendige Verbindungs- und Authentifizierungsdaten sowie die für die gewählte Funktion erforderlichen Angaben, etwa Medienkennung, Wiedergabeposition oder Änderungen an Playlists. Er liefert Medien, Verzeichnisse und Metadaten an dein Gerät. Kurzlebige Streaming-Tickets ermöglichen die Wiedergabe.</p><p>Mit der Mediaserver-Serversoftware kann der Server optional selbst öffentliche Informationen nachschlagen: Namen von Interpreten, Alben, Titeln, Serien und Filmen aus deiner Bibliothek werden dabei an die iTunes Search API (Apple), Wikipedia (Wikimedia Foundation), MusicBrainz und Cover Art Archive (MetaBrainz Foundation, Internet Archive), TVmaze, LRCLIB und Genius übermittelt, um Beschreibungen, Cover, Poster, Folgentitel und Songtexte zu erhalten. Diese Anfragen gehen vom Server aus, nicht von deinem iPhone oder iPad, und enthalten weder Zugangsdaten noch Dateipfade; die Dienste sehen die IP-Adresse des Servers. Ergebnisse werden auf dem Server gespeichert. Der Serverbetreiber kann die Funktion abschalten (MINIPLY_ONLINE_METADATA=0).</p><h3 id="web-player">Web-Player</h3><p>Die Mediaserver-Serversoftware stellt unter der Adresse deines Servers einen Player für den Browser bereit. Er meldet sich mit demselben Zugangs-Token an wie die App und spricht nur mit deinem Server. Wählst du „Auf diesem Gerät angemeldet bleiben“, speichert der Browser das Token und eine zufällige Gerätekennung in seinem lokalen Speicher (localStorage), sonst das Token nur bis zum Schließen des Fensters (sessionStorage); „Abmelden“ löscht das Token. Wie die App gleicht der Web-Player Gesehen-Markierungen, zuletzt Gespieltes und Wiedergabepositionen mit deinem Server ab. Er setzt keine Cookies und lädt keine fremden Skripte oder Schriften. Eine Ausnahme sind die Cover aus dem iTunes-Katalog auf Interpretenseiten: Diese Bilder lädt dein Browser direkt von Apples Bildserver (mzstatic.com), sodass Apple dabei deine IP-Adresse und die angefragten Bilder sieht. Cover aus deiner eigenen Bibliothek kommen weiterhin von deinem Server.</p><h3 id="musik-finden">Musik finden</h3><p>Suchst du in der App unter „Musik finden“, schickt der Server deine Suchwörter an die iTunes Search API (Apple), um Songs, Alben und Künstlerseiten anzuzeigen; fehlende Titellisten ergänzt er über Genius. Lädst du etwas auf den Server, sucht der Musikdienst des Servers die Aufnahme bei YouTube Music (Google) und lädt sie mit dem Programm yt-dlp herunter. Dabei gehen Titel, Künstler und Album an YouTube. Aktualisierungen von yt-dlp bezieht der Server von GitHub. Damit die Suche schnell antwortet, hält der Server eine Kopie des iTunes-Katalogs: Er fragt Ranglisten beliebter Künstler bei Deezer (Deezer S.A.), ListenBrainz (MetaBrainz Foundation) und den Apple-Music-Charts ab und lädt deren Songs und Alben von der iTunes Search API. Auch diese Anfragen gehen vom Server aus, nicht von deinem Gerät, enthalten weder Zugangsdaten noch Angaben zu dir, und die Dienste sehen die IP-Adresse des Servers. Der Serverbetreiber kann den Katalog abschalten (MINIPLY_MUSIC_CATALOG=0); ohne eingerichteten Musikdienst gibt es „Musik finden“ nicht. Nutze die Funktion nur für Inhalte, für die du die erforderlichen Rechte hast. Lädst du Dateien aus der App hoch, werden sie an deinen Server übertragen und dort gespeichert. Favoriten, Hörstatistik und Gesehen-Markierungen speichert die App auf deinem Gerät und gleicht sie mit deinem Server ab, damit sie auf deinen Geräten übereinstimmen.</p><p>Wir erhalten diese Daten nicht automatisch. Wenn du einen eigenen Server oder den Server eines Dritten verwendest, ist dessen Betreiber für die dortige Verarbeitung, Zugriffsrechte, Protokolle, Sicherungen und Löschung verantwortlich. Nutze ausschließlich Server, denen du vertraust. Ein vom Betreiber eingesetzter HTTPS-Proxy kann Medien während der Übertragung verarbeiten, auch wenn er keine dauerhaften Kopien anlegt.</p><p>Soweit wir selbst einen ausdrücklich bereitgestellten Testserver betreiben, verarbeitet dieser nur bereitgestellte Beispieldateien, technisch notwendige Anfragen sowie während des Tests angelegte Playlists und Wiedergabepositionen. Ein gemeinsamer Testzugang ist nicht persönlich: Teständerungen können für andere Testnutzer sichtbar sein. Gib dort keine persönlichen Inhalte ein. Die Testdaten können jederzeit zurückgesetzt werden. Rechtsgrundlagen für von uns angebotene Funktionen sind Art. 6 Abs. 1 lit. b DSGVO und für deren Absicherung Art. 6 Abs. 1 lit. f DSGVO. Für eigens gespeicherte Serverdaten gelten die Regeln des jeweiligen Betreibers.</p></section><section id="kontakt"><h2>5. E-Mail und Support</h2><p>Wenn du uns schreibst, verarbeiten wir deine E-Mail-Adresse, den Inhalt der Anfrage und freiwillig übermittelte technische Angaben zur Beantwortung. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO bei vertragsbezogenen Anfragen, ansonsten Art. 6 Abs. 1 lit. f DSGVO aufgrund unseres Interesses an der Bearbeitung deiner Nachricht. Die Kommunikation läuft über unsere E-Mail-Dienstleister.</p><p>Sende keine Passwörter, API-Tokens oder privaten Mediendateien. Wir verwenden Supportanfragen nicht für Werbung. Nach abschließender Bearbeitung löschen wir die Anfrage, sobald sie nicht mehr zur Nachverfolgung erforderlich ist; regelmäßig spätestens nach sechs Monaten, sofern keine gesetzlichen Aufbewahrungspflichten oder konkreten Rechtsansprüche entgegenstehen.</p></section><section id="loeschung"><h2>6. Speicherfristen und Löschen</h2><ul><li><strong>Verbindung:</strong> „Server → Verbindung entfernen“ löscht die gespeicherten Verbindungsdaten aus dem Schlüsselbund. Schlüsselbunddaten können eine Deinstallation überdauern; entferne die Verbindung daher vorher in der App.</li><li><strong>Downloads:</strong> Entferne Dateien im Download-Tab. Beim Trennen einer Verbindung bleiben Downloads erhalten. Eine vollständige Löschung der App entfernt den lokalen App-Dateibestand; „App auslagern“ ist dafür nicht ausreichend.</li><li><strong>Cache und Einstellungen:</strong> Diese bleiben für die App-Nutzung auf dem Gerät. Durch vollständige Löschung der App wird ihr lokaler Datenbestand entfernt. Vorhandene Gerätesicherungen verwaltest du separat bei Apple oder auf deinem Computer.</li><li><strong>Server:</strong> Wiedergabepositionen und Playlists können auf dem Medienserver gespeichert sein. Wende dich für Löschung und Sicherungen an dessen Betreiber. Eine Deinstallation löscht keine Serverdaten und keine Originalmedien.</li><li><strong>Support und Website:</strong> Es gelten die oben genannten zweckbezogenen Fristen.</li></ul><h2>7. Empfänger und Übermittlungen</h2><p>Empfänger sind, soweit für den jeweiligen Vorgang erforderlich, Hosting- und E-Mail-Dienstleister, der von dir ausgewählte Medienserver, bei eingeschalteten Ausfall-Warnungen der Apple Push Notification Service, beim Öffnen einer Interpretenseite im Web-Player Apples Bildserver sowie die in Abschnitt 4 genannten Dienste, die der Server selbst anfragt. Apple verarbeitet den Bezug der App, Betriebssystemfunktionen und gegebenenfalls freiwillig freigegebene Diagnosedaten nach eigenen Datenschutzbestimmungen. Wir integrieren keine Analyseplattform und verkaufen keine personenbezogenen Daten. Bei Nutzung eines Servers außerhalb der EU oder des EWR bestimmt dessen Betreiber die dortigen Verarbeitungsbedingungen.</p></section><section id="rechte"><h2>8. Deine Rechte</h2><p>Im gesetzlichen Umfang hast du Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung und Datenübertragbarkeit. Eine erteilte Einwilligung kannst du jederzeit mit Wirkung für die Zukunft widerrufen. Der Widerruf berührt nicht die Rechtmäßigkeit der bisherigen Verarbeitung.</p><p><strong>Widerspruch:</strong> Soweit eine Verarbeitung auf Art. 6 Abs. 1 lit. f DSGVO beruht, kannst du aus Gründen, die sich aus deiner besonderen Situation ergeben, widersprechen. Schreibe dazu an die oben genannte Kontaktadresse.</p><p>Du kannst dich bei einer Datenschutzaufsichtsbehörde beschweren, insbesondere an deinem Aufenthaltsort, Arbeitsplatz oder am Ort eines vermuteten Verstoßes. Für Sachsen ist die Sächsische Datenschutz- und Transparenzbeauftragte zuständig: <a href="https://www.datenschutz.sachsen.de/">datenschutz.sachsen.de</a>.</p><p>Es findet durch uns keine automatisierte Entscheidungsfindung einschließlich Profiling mit rechtlicher oder vergleichbar erheblicher Wirkung statt. Eine gesetzliche Pflicht zur Übermittlung von Supportdaten besteht nicht; ohne notwendige Angaben kann eine Anfrage unter Umständen nicht bearbeitet werden.</p><h2>9. Änderungen</h2><p>Diese Erklärung wird bei Änderungen der Funktionen oder Datenverarbeitung angepasst. Die aktuelle Fassung und ihr Datum findest du auf dieser Seite.</p></section>'''
